INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65652, 'spa', 'declarar justo', 'declarar justo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65655, 'spa', 'vindicar o reconocer como justo', 'vindicar o reconocer como justo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65661, 'spa', 'justificarse a sí mismo', 'justificarse a sí mismo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65672, 'spa', 'Regulación, ordenanza', 'Regulación, ordenanza. Decreto, estatuto o regulación concreta prescrita por autoridad divina o legal. Este es el sentido más frecuente en el NT, abarcando las ordenanzas mosaicas (Hebreos 9:1, 10), los justos requisitos de la Ley (Romanos 2:26; 8:4) y el justo decreto de Dios de que el pecado merece la muerte (Romanos 1:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65673, 'spa', 'Obra justa, acto de justicia', 'Obra justa, acto de justicia. Obra justa o acto de rectitud moral realizado por una persona o atribuido colectivamente a los santos. En Apocalipsis 19:8 el lino fino son las ''obras justas'' de los santos; en Apocalipsis 15:4 se revelan los actos justos de Dios. Romanos 5:18 lo usa para el único ''acto de justicia'' de Cristo que conduce a la justificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65679, 'spa', 'Justificación, acto de absolución', 'Justificación, acto de absolución. El acto judicial de absolución o declaración de justicia: el veredicto de Dios que pronuncia justo al pecador. En Romanos 5:16 el don gratuito tras muchas transgresiones conduce a la ''justificación'' (δικαίωμα), contrastando con la condenación del pecado de Adán. Este es un sentido distintivamente paulino con carácter forense y judicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65680, 'spa', 'Justa y rectamente', 'De manera justa, recta o moralmente íntegra; actuando conforme a lo que es correcto ante Dios y la conciencia humana. El ladrón moribundo confiesa que su castigo es merecido (Lucas 23:41), Pablo invoca esta palabra para describir su conducta intachable entre los creyentes (1 Tesalonicenses 2:10), y en Tito 2:12 forma parte de una tríada que describe la vida cristiana sobria, justa y piadosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65681, 'spa', 'Justificación divina', 'Ambas ocurrencias están en el argumento central de Romanos sobre la justificación: Cristo resucitado para nuestra ''justificación'' (Romanos 4:25), y el don gratuito que trae ''justificación'' de vida en contraste con la condenación (Romanos 5:18). El término captura el acto divino decisivo que establece la posición correcta delante de Dios, revirtiendo el veredicto de culpa. El uso paulino lo convierte en un término teológico técnico para el acto salvífico central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65682, 'spa', 'Juez/árbitro', 'Ambas instancias están en el discurso de Esteban, citando el rechazo israelita a Moisés: ''¿Quién te puso por gobernante y juez sobre nosotros?'' (Hechos 7:27, 7:35). La ocurrencia pareada en una sola narrativa enfatiza la ironía—Israel rechazó al líder-juez que Dios mismo había designado. El término designa a alguien con autoridad para resolver disputas y emitir decisiones judiciales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65683, 'spa', 'Justicia retributiva divina', 'En las tres apariciones neotestamentarias, δίκη designa la justicia retributiva o el castigo divino. Hechos 28:4 personifica notablemente a la Justicia como deidad perseguidora: los bárbaros interpretan la mordedura de la serpiente como prueba de que la Justicia no lo dejó vivir. En 2 Tesalonicenses 1:9 y Judas 1:7 el término denota el castigo mismo: destrucción eterna, fuego eterno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65684, 'spa', 'Red de pesca — la herramienta principal del oficio pesquero galileo, usada en lo', 'Red de pesca — la herramienta principal del oficio pesquero galileo, usada en los relatos de llamamiento y las historias de pesca milagrosa. Simón y Andrés echan su red (Mt 4:18; Mr 1:16); Jacobo y Juan remienden las suyas (Mt 4:21; Mr 1:19). Las dos pescas milagrosas (Lc 5:4-7 donde las redes casi se rompen; Jn 21:6-11 donde la red sostiene 153 peces intacta) invisten a la red de peso simbólico como imagen de la misión apostólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65687, 'spa', 'Doblez en el hablar', 'La instrucción de Pablo a Timoteo (1 Tim 3:8) exige que los diáconos no sean de doble lengua, es decir, que no hablen de un modo ante un grupo y de otro ante otro con fines manipuladores. Describe una duplicidad deliberada en la comunicación, falta fundamental contra la integridad requerida para el servicio eclesial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65688, 'spa', 'por lo cual, por eso', 'Conjuncion ilativa fuerte que significa ''por lo cual'' o ''por esta razon'', e introduce una conclusion que se sigue necesariamente del argumento o la narrativa precedente. Mas enfatica que oun, marca inferencias culminantes en el razonamiento teologico (Ro 1:24 ''por lo cual Dios los entrego''; Fil 2:9 ''por lo cual Dios le exalto'') y exhortaciones decisivas (1 Co 10:14 ''por tanto, huid de la idolatria'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65690, 'spa', 'Viaje itinerante', 'Ambas ocurrencias describen ministerio o viaje itinerante: Jesús ''viajando a través'' de ciudades y aldeas predicando el reino (Lucas 8:1), y Pablo y Silas ''pasando por'' Anfípolis y Apolonia camino a Tesalónica (Hechos 17:1). El verbo enfatiza movimiento a través del territorio, tocando múltiples ubicaciones en lugar de establecerse en un solo lugar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65691, 'spa', 'Converso ateniense', 'Hechos 17:34 menciona a Dionisio como uno de los conversos atenienses tras el discurso de Pablo en el Areópago. Su nombre teofórico, derivado del dios Dioniso, era común en la cultura griega. La inclusión de su nombre por Lucas sugiere que llegó a ser un miembro notable de la comunidad cristiana ateniense.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65692, 'spa', 'Inferencia causal', 'Ambos usos en 1 Corintios introducen imperativos prácticos basados en razonamiento teológico: ''Por lo tanto'' si la comida causa tropiezo, Pablo se abstendrá (1 Corintios 8:13), y ''Por lo tanto'' huid de la idolatría dada la incompatibilidad de comunión con Cristo y con demonios (1 Corintios 10:14). La conjunción señala inferencia lógica fuerte desde el argumento previo hacia la acción consecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65693, 'spa', 'Caído del cielo', 'El secretario municipal de Éfeso (Hechos 19:35) calma el tumulto afirmando que todos saben que Éfeso custodia el templo de Artemisa y la imagen ''caída de Zeus'', es decir, del cielo. Esto refleja la creencia pagana en imágenes de culto de origen meteorítico. El español ''caída del cielo'' capta mejor el sentido que una referencia literal a Zeus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65694, 'spa', 'Reforma/corrección', 'Dos contextos contrastantes: elogiando las ''reformas'' logradas bajo el gobierno de Félix (Hechos 24:2), y describiendo las regulaciones del antiguo pacto como válidas solo hasta el tiempo de ''reforma'' traída por Cristo (Hebreos 9:10). Ambos involucran corrección o mejora sistemática, aunque Hebreos le da significado escatológico como la era del nuevo ordenamiento divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65695, 'spa', 'Perforar un muro', 'Cavar o abrir un boquete a través de las paredes de adobe o tierra de una casa para entrar como ladrón. Jesús emplea esta imagen al contrastar el tesoro terrenal con el celestial (Mt 6:19-20), donde la polilla corroe y los ladrones διορύσσουσιν (''perforan''). El mismo verbo aparece en las parábolas del amo de casa (Mt 24:43; Lc 12:39), advirtiendo contra la entrada furtiva e inesperada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65696, 'spa', 'Gemelos divinos protectores', 'Hechos 28:11 identifica el navío de Pablo por su mascarón de proa: los Dióscuros, los gemelos Cástor y Pólux, protectores de los marineros en la creencia grecorromana. Los mascarones invocaban protección divina para los viajes, y esta referencia muestra cómo los símbolos paganos impregnaban la cultura marítima antigua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65697, 'spa', 'Conjunción causal', 'Conjunción causal: ''porque, puesto que, por la razón de que,'' introduciendo el fundamento o la explicación de una afirmación previa. Este es el uso dominante en las 21 ocurrencias. Lucas es especialmente afín a este término: la tranquilización del ángel en Lc 1:13, el detalle de la natividad en Lc 2:7 y la promesa escatológica de Lc 21:28. Pablo lo emplea en Ro 1:19-21 y Hch 18:10.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65698, 'spa', 'Conjunción inferencial', 'Conjunción inferencial: ''por lo cual, por eso,'' extrayendo una conclusión de lo que precede en vez de proporcionar una causa. En Hechos 13:35 Pablo cita un salmo como evidencia y extrae una conclusión (''por eso dice también en otro salmo''), y en Hechos 20:26 se declara inocente de toda sangre ''por lo cual.'' Este sentido inferencial es minoritario pero claramente distinto del causal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65699, 'spa', 'Nombre propio personal', '3 Juan 9 menciona a Diótrefes como alguien que ''ama ser el primero'' y rechaza la autoridad apostólica. Su nombre, derivado de Zeus, era típico en la cultura griega. La crítica de Juan revela un conflicto temprano en la iglesia entre líderes locales y la supervisión apostólica. Las traducciones en distintas lenguas conservan el nombre griego con diversas transliteraciones, al tratarse de un nombre propio que designa a un individuo específico que encarnaba la autopromoción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65700, 'spa', 'Doble o duplicado', 'Doble o dos veces más en cantidad, grado o medida, ya sea literal o intensificado. La reprensión de Jesús sobre los fariseos que hacen a un prosélito ''doble hijo de la Gehena'' (Mt 23:15) usa el término como intensificación moral; los ancianos merecen ''doble honor'' (1 Ti 5:17) por su fiel servicio; y Babilonia recibe ''doble'' retribución por sus pecados (Ap 18:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65701, 'spa', 'Duplicar en juicio', 'Apocalipsis 18:6 ordena que a Babilonia se le devuelva ''el doble'' por sus obras, una imagen vívida de justicia divina integral. El concepto griego implica multiplicar por dos o repetir algo de manera doble. El español ''doblad'', el francés ''doubler'' y el inglés ''double'' capturan tanto el sentido matemático como el retributivo: un pago completo multiplicado donde nada queda sin saldar en el juicio de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65702, 'spa', 'Dos veces', 'Adverbio temporal-cuantitativo directo que significa ''dos veces'', marcando la repetición de una acción u ocurrencia. Seis de siete usos neotestamentarios caen aquí, abarcando la escena de la negación de Pedro donde el gallo canta ''dos veces'' (Mr 14:30, 72), la pretensión farisaica de ayunar ''dos veces por semana'' (Lc 18:12), y los repetidos intentos de Pablo de visitar Tesalónica (Fil 4:16; 1 Ts 2:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65704, 'spa', 'Dos miríadas', 'Uso numérico compuesto en Apocalipsis 9:16, donde δίς aparece como parte de la frase δισμυριάδες μυριάδων (''dos miríadas de miríadas''), designando un vasto ejército de doscientos millones. No se trata de ''dos veces'' en sentido iterativo, sino del numeral ''dos'' funcionando como multiplicador dentro de una expresión compuesta para una hueste militar apocalíptica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65705, 'spa', 'Dudar ante lo sobrenatural', 'Ambas instancias de Mateo involucran duda ante lo sobrenatural: Jesús reprendiendo la ''duda'' de Pedro mientras se hundía durante la caminata sobre el agua (Mateo 14:31: español ''dudaste''), y algunos discípulos ''dudando'' incluso al ver a Jesús resucitado (Mateo 28:17: español ''dudaron''). El verbo captura el vacilar entre fe e incredulidad, la mente dividida en momentos que requieren confianza sobrenatural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65706, 'spa', 'Espada de doble filo', 'Los tres usos neotestamentarios aplican ''de doble filo'' a la imagen de la espada como palabra divina. Hebreos 4:12 lo emplea en la célebre descripción de la palabra de Dios como ''viva y eficaz, más cortante que toda espada de dos filos, que penetra hasta partir el alma y el espíritu.'' Apocalipsis 1:16 y 2:12 representan una espada aguda de dos filos saliendo de la boca del Hijo del Hombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65707, 'spa', 'Cantidad numérica', 'Marcos 5:13 precisa que unos dos mil cerdos se ahogaron tras la expulsión de los demonios por Jesús. La cifra exacta resalta la escala enorme del milagro y el impacto económico en la región. Todas las tradiciones lingüísticas lo vierten de modo directo como ''dos mil'' — en español, francés ''deux mille'', alemán ''zweitausend'' — pues se trata de una designación numérica simple que no requiere adaptación cultural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65708, 'spa', 'Colar o filtrar', 'Mateo 23:24 presenta la mordaz crítica de Jesús: los líderes religiosos cuelan mosquitos (insectos diminutos ritualmente impuros) mientras se tragan camellos (animales impuros de gran tamaño). El verbo describe el filtrado cuidadoso para eliminar partículas mínimas, usado metafóricamente para la atención obsesiva a detalles legales menores. El español ''coláis'', el francés ''filtrer'' y el inglés ''straining out'' capturan por igual la imagen del colado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65709, 'spa', 'Dividir o separar', 'Mateo 10:35 emplea este verbo para el propósito de Jesús de ''dividir'': enfrentar a miembros de una familia entre sí mediante las exigencias radicales del discipulado. El término transmite la separación en dos partes opuestas. El español ''dividir'', el francés ''diviser'' y el inglés ''to divide'' expresan esta escisión fundamental. La declaración de Jesús reconoce que seguirle genera divisiones inevitables cuando unos aceptan y otros rechazan su llamado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65710, 'spa', 'Divisiones destructivas', 'Los dos usos de Pablo identifican las divisiones como destructivas: advirtiendo evitar a quienes causan ''divisiones'' contrarias a la enseñanza recibida (Romanos 16:17), y enumerando ''disensiones'' entre obras carnales opuestas al fruto del Espíritu (Gálatas 5:20: español ''divisiones'', alemán ''Zwietracht''). Ambos contextos condenan la división como dañina a la unidad comunitaria y contraria a los valores del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65711, 'spa', 'Juicio severo', 'Usos paralelos en las parábolas de Jesús sobre siervos infieles: el amo ''cortará en dos'' al siervo malvado que abusa de su posición (Mateo 24:51, Lucas 12:46: francés ''couper en deux''). Ya sea literal o metafórico, el término enfatiza la severidad y finalidad del juicio sobre mayordomos infieles. La imaginería gráfica hace la consecuencia inequívocamente seria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65712, 'spa', 'Tener sed, estar sediento', 'Tener sed, estar sediento: experimentar sed, ya sea como necesidad fisiologica literal de agua (Mt 25:35, 37, 42, 44; Jn 19:28; Ro 12:20; 1 Co 4:11) o como metafora de profundo anhelo espiritual y deseo de Dios o de justicia (Mt 5:6; Jn 4:13-14; 6:35; 7:37; Ap 21:6; 22:17). El propio grito de Jesus ''Tengo sed'' en la cruz (Jn 19:28) resuena en ambos niveles simultaneamente. El uso metaforico se nutre de la tradicion profetica que presenta la sed como imagen del anhelo del alma por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65722, 'spa', 'Sed física', 'En 2 Corintios 11:27, Pablo incluye la sed en su catálogo de padecimientos apostólicos, junto con el hambre, el frío y la desnudez. Se trata de sed física literal, la necesidad corporal de agua durante los arduos viajes misioneros. La disposición de Pablo a soportar privaciones tan básicas subraya su entrega total al evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65723, 'spa', 'Lealtad dividida', 'Los dos usos de Santiago condenan la lealtad dividida: el hombre ''de doble ánimo'' es inestable en todos sus caminos (Santiago 1:8), y los pecadores deben purificar corazones porque son ''de doble ánimo'' (Santiago 4:8: español ''de doble ánimo''). El término diagnostica un problema fundamental—división interna entre lealtades competidoras (típicamente Dios y mundo) que produce inestabilidad y previene devoción total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65724, 'spa', 'Persecución', 'Persecución. Hostigamiento sistemático u opresión dirigida contra los creyentes por causa de su fe. Jesús enseña que la persecución pone a prueba a quienes reciben la palabra con gozo inicialmente (Mateo 13:21; Marcos 4:17) y acompaña la recompensa centuplicada del discipulado (Marcos 10:30). La iglesia posterior a Pentecostés la experimentó de manera colectiva (Hechos 8:1; 13:50), y Pablo la enumera entre las tribulaciones que no pueden separarnos del amor de Cristo (Romanos 8:35; 2 Corintios 12:10; 2 Timoteo 3:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65728, 'spa', 'Perseguidor hostil', 'En 1 Timoteo 1:13, Pablo confiesa haber sido perseguidor de la iglesia, alguien que activamente cazaba a los creyentes. El griego enfatiza la persecución agresiva con intención hostil. El español «perseguidor» capta este sentido de quien acosa a sus víctimas. Su reconocimiento franco de esa violencia magnifica la gracia transformadora de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65729, 'spa', 'perseguir, oprimir', 'perseguir, oprimir');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65731, 'spa', 'buscar, esforzarse por alcanzar', 'buscar, esforzarse por alcanzar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65737, 'spa', 'ser perseguido, sufrir persecución', 'ser perseguido, sufrir persecución');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65755, 'spa', 'Decreto u ordenanza', 'Un decreto, ordenanza o regulación formal emitida por una autoridad, ya sea imperial, apostólica o religiosa. El alcance va desde el decreto de censo de César (Lucas 2:1), pasando por las decisiones del concilio apostólico (Hechos 16:4), hasta el código escrito de regulaciones legales judías (Efesios 2:15; Colosenses 2:14). El español distingue «decreto» para edictos imperiales de «ordenanzas» para estatutos religiosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65756, 'spa', 'Someterse a decretos', 'Colosenses 2:20 cuestiona por qué los creyentes se someten a regulaciones («No manejes, no gustes») cuando han muerto con Cristo a los principios mundanos. El verbo enfatiza la aceptación voluntaria de normas impuestas desde fuera. Pablo desafía el retorno a prácticas legalistas que contradicen la libertad lograda en Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65757, 'spa', 'parecer, aparentar', 'Parecer o dar la impresion: la palabra se vuelve hacia afuera, del pensamiento privado a la impresion publica. Algo da la apariencia de ser de cierta manera ante un observador. En Mt 21:28 Jesus pregunta ''?Que os parece?'' y en Mt 22:17 los fariseos preguntan que ''parece correcto'' respecto al tributo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65758, 'spa', 'pensar, suponer, creer', 'El nucleo cognitivo: pensar, suponer o sostener una opinion. Es el sentido mas frecuente (37 ocurrencias), empleado cuando alguien forma un juicio o alberga una creencia. Las incisivas preguntas de Jesus ''?Pensais que...?'' (Mt 3:9; 26:53) y los desafios retoricos de Pablo despliegan este sentido para provocar reflexion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65760, 'spa', 'parecer bien, decidir', 'Uso impersonal deliberativo: ''parecio bien'' o ''se decidio''. Lucas 1:3 —''me parecio bien a mi tambien''— y los decretos del concilio de Jerusalen en Hechos 15 (vv. 22, 25, 28) emplean esta construccion para decisiones formales o meditadas. Marca un juicio colectivo o autoritativo, no una mera opinion privada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65761, 'spa', 'ser estimado, ser reputado', 'Ser considerado, estimado o tenido por importante. En Galatas 2:2, 6, 9, Pablo se refiere a ''los que parecian ser columnas'': lideres cuya reputacion los precedia. Marcos 10:42 describe de modo similar a gobernantes que ''son tenidos por'' tales. No se trata de lo que alguien piensa en privado, sino del reconocimiento y la posicion publica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65781, 'spa', 'Sentido cognitivo refinado de discernimiento', 'Sentido cognitivo refinado de discernimiento: la capacidad de interpretar señales, distinguir el bien del mal y evaluar lo que es verdaderamente apropiado. Lucas 12:56 es el pasaje definitorio: Jesús reprende a las multitudes que saben interpretar el cielo pero no el kairos (''este tiempo presente''). Romanos 12:2 insta a los creyentes a ''discernir'' la voluntad de Dios mediante la renovación de la mente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65782, 'spa', 'Sentido fundamental de probar, examinar o verificar la calidad y autenticidad de', 'Sentido fundamental de probar, examinar o verificar la calidad y autenticidad de algo o alguien. Desde el ensayo de metales en el uso clásico hasta la exhortación de Pablo ''examínese cada uno a sí mismo'' (1 Co 11:28), este sentido impregna el NT. Un hombre prueba sus bueyes nuevos (Lc 14:19), el fuego prueba la obra de cada constructor (1 Co 3:13). La idea central es someter algo a escrutinio para verificar su genuinidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65783, 'spa', 'Sentido culminante de aprobación tras examen', 'Sentido culminante de aprobación tras examen: declarar a alguien o algo digno y apto. En 1 Ts 2:4 Pablo dice que Dios ''aprobó'' (δεδοκιμάσμεθα) a los apóstoles para que se les confiara el evangelio. Romanos 14:22 habla de la bienaventuranza de quien no se condena a sí mismo en lo que ''aprueba.'' Este sentido presupone un proceso de prueba previo cuyo resultado es un veredicto favorable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65801, 'spa', 'Prueba, evidencia', 'Demostración concreta o evidencia que valida una afirmación: la prueba tangible de algo profesado. Pablo apela a este sentido cuando escribe sobre buscar ''la prueba de vuestra obediencia'' (2 Corintios 2:9) y ''la prueba de vuestro ministerio'' (2 Corintios 9:13). El español ''prueba'' y el alemán ''Prüfung'' portan este matiz probatorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65802, 'spa', 'Carácter probado', 'La cualidad de carácter que emerge al soportar pruebas: una fibra moral probada y templada. Romanos 5:4 presenta la famosa progresión donde la tribulación produce paciencia y la paciencia produce δοκιμή. En Filipenses 2:22 se elogia el carácter probado de Timoteo. Las traducciones al español distinguen aquí con ''carácter probado'', separando el resultado del proceso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65803, 'spa', 'Prueba, ordalia', 'El proceso o experiencia de ser puesto a prueba, una ordalia o tribulación que somete la fe a verificación. En 2 Corintios 8:2, la ''gran prueba de aflicción'' de las iglesias de Macedonia desbordó en generosidad. Hebreos 3:9 cita el Salmo 95 donde Israel puso a prueba a Dios en el desierto. El francés ''épreuve'' y el español ''prueba'' abarcan tanto este sentido procesual como el probatorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65805, 'spa', 'Prueba de fe', 'Ambas ocurrencias se relacionan con la fe siendo probada a través de ensayos: la ''prueba'' de la fe produce perseverancia (Santiago 1:3: español ''prueba''), y la ''autenticidad'' de la fe, más preciosa que el oro, se revela a través de prueba como fuego (1 Pedro 1:7). El término enfatiza la función probatoria—ensayos que prueban y así demuestran o desarrollan fe genuina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65806, 'spa', 'Aprobado, probado genuino', 'Probado y hallado genuino, aprobado tras examen; describe a una persona o cualidad que ha sido puesta a prueba y demostrada digna de confianza. Se usa para referirse al caracter aprobado por Dios (Rom 14:18, ''acepto a Dios y aprobado por los hombres''; 2 Cor 10:18, ''no el que se recomienda a si mismo, sino aquel a quien el Senor recomienda''), de individuos especificos (Rom 16:10, Apeles ''aprobado en Cristo''), y del proceso mismo de prueba (1 Cor 11:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65810, 'spa', 'Viga, madero grande', 'Una viga o madero estructural de gran tamano, usado literalmente en la construccion y figuradamente por Jesus para representar una falta personal grave que ciega ante los defectos menores de otros. Aparece exclusivamente en el dicho de ''la viga y la pajilla'' (Mat 7:3-5; Luc 6:41-42), donde la imagen absurda de una viga alojada en el ojo dramatiza la insensatez del juicio hipocrita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65811, 'spa', 'Engañoso y artero', 'En 2 Corintios 11:13, Pablo identifica a sus oponentes como «obreros engañosos» que se hacen pasar por apóstoles genuinos. El adjetivo describe a quienes actúan mediante manipulación astuta y fraude. Su astucia implica una tergiversación deliberada de la verdad para explotar a los creyentes en beneficio propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65812, 'spa', 'Engañar con astucia', 'En Romanos 3:13 se cita la Septuaginta: «con sus lenguas engañaban», donde el imperfecto sugiere acción traicionera continua. El verbo describe el obrar con dolo hacia otros. Pablo emplea esta cita veterotestamentaria para demostrar que la corrupción del lenguaje evidencia la depravación universal del ser humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65813, 'spa', 'Engaño, astucia, doblez', 'Engaño, astucia, doblez. Decepción deliberada, traición o maquinación empleada para confundir o perjudicar. Se usa para las conspiraciones hostiles contra Jesús (Mateo 26:4; Marcos 14:1), en listas de vicios (Marcos 7:22; Romanos 1:29; 1 Pedro 2:1) y para caracterizar a Elimas (Hechos 13:10). Su ausencia marca integridad: Natanael ''sin engaño'' (Juan 1:47) y Cristo sin ''engaño alguno en su boca'' (1 Pedro 2:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65817, 'spa', 'Adulterar, falsificar', 'En 2 Corintios 4:2, Pablo renuncia a la practica de ''adulterar la palabra de Dios'', es decir, corromper o manipular las Escrituras con fines egoistas. El verbo describe la accion de mezclar elementos ajenos para defraudar, como diluir vino o alear oro con metales inferiores. Pablo insiste en la transparencia y la integridad al proclamar el mensaje divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65818, 'spa', 'Don otorgado', 'Un don o cosa otorgada, enfatizando el objeto concreto dado más que el acto abstracto de dar. Jesús usa este término en su argumento a fortiori sobre la generosidad del Padre: si los padres humanos, siendo imperfectos, dan buenos δόματα a sus hijos, cuánto más el Padre celestial (Mt 7:11; Lc 11:13). Pablo cita el Sal 68:18 en Ef 4:8, declarando que el Cristo ascendido distribuyó δόματα a su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65819, 'spa', 'gloria, esplendor divino', 'La magnificencia radiante, el honor y la soberana majestad de Dios, manifestados visiblemente o reconocidos por las criaturas. Con 167 ocurrencias, abarca la gloria del reino de Dios (Mt 6:13), el Cristo transfigurado (Lc 9:32), la esperanza de la glorificación futura (Ro 5:2) y la alabanza doxológica (Fil 4:20). La convergencia interlingüística — español «gloria», árabe «مجد», coreano «영광» — atestigua su unidad semántica nuclear.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65825, 'spa', 'ser glorificado, recibir gloria', 'Ser glorificado, recibir gloria o ver revelada la propia gloria: el pasivo divino que describe la gloria conferida y no otorgada. Central en la teologia juanina, donde Jesus es glorificado mediante su muerte y resurreccion (Jn 7:39; 12:16, 23; 13:31) y el Padre y el Hijo se glorifican mutuamente (Jn 17:1, 4-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65826, 'spa', 'glorificar, alabar activamente', 'Atribuir activamente gloria, honor y alabanza a Dios o a otro: el sentido transitivo de rendir gloria. Este uso dominante (43 ocurrencias) abarca respuestas narrativas a milagros (Mt 9:8; Mr 2:12; Lc 2:20), mandatos de glorificar a Dios (Mt 5:16; 1 Co 6:20) y declaraciones doxologicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65856, 'spa', 'Nombre propio (Dorcas)', 'El nombre propio aparece dos veces en la narración de la resurrección en Hechos 9: presentándola como ''Dorcas'' (también llamada Tabita), llena de buenas obras (Hechos 9:36), y nombrándola nuevamente cuando Pedro encuentra a las viudas de luto mostrando las vestiduras que ''Dorcas'' había hecho (Hechos 9:39). El nombre griego (gacela) se empareja con el arameo Tabita para identificar a esta mujer caritativa cuya resurrección testificó poderosamente de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65857, 'spa', 'Acto de dar', 'Pablo elogia la participación única de los filipenses en ''dar y recibir'' durante el ministerio inicial del evangelio (Filipenses 4:15: español ''de dar''), y Santiago contrasta la variabilidad terrenal con la naturaleza inmutable de Dios en el ''dar'' (Santiago 1:17). Ambos usos enfatizan el acto o patrón de dar más que dones específicos, destacando la dimensión relacional del otorgamiento y el intercambio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65858, 'spa', 'Dador, donante', 'En 2 Corintios 9:7, Pablo declara que Dios ama al ''dador alegre'', aquel cuya generosidad brota del gozo y no de la obligacion. El sustantivo enfatiza el caracter de la persona como alguien que da. La ensenanza de Pablo eleva la disposicion generosa por encima de la obligacion mecanica: Dios se deleita en quienes dan con alegria de corazon.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65859, 'spa', 'Esclavizar, someter', 'En 1 Corintios 9:27, Pablo declara que disciplina su cuerpo y ''lo pone en servidumbre'', ejerciendo un dominio estricto sobre los deseos fisicos como un atleta en entrenamiento. El verbo conlleva la fuerza de esclavizar o sojuzgar. Pablo practica esta autodisciplina voluntaria para que su cuerpo no comprometa la integridad de su ministerio apostolico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65860, 'spa', 'Esclavitud o servidumbre', 'La condición de esclavitud o servidumbre, empleada metafóricamente en el NT para referirse a la subyugación espiritual y existencial. Pablo la despliega como antítesis de la libertad cristiana: un «espíritu de esclavitud» que conduce al temor frente a la adopción como hijos (Romanos 8:15), la «servidumbre de la corrupción» de la que la creación espera ser liberada (Romanos 8:21), y el «yugo de esclavitud» que el legalismo reimpondría sobre los libertos (Gálatas 5:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65861, 'spa', 'Servir, prestar servicio devoto o cumplir deberes en nombre de un amo, señor o c', 'Servir, prestar servicio devoto o cumplir deberes en nombre de un amo, señor o causa, ya sea divina o humana. Jesús declara la imposibilidad de servir a dos señores a la vez: Dios y las riquezas (Mt 6:24; Lc 16:13). El hijo mayor ha ''servido'' fielmente a su padre (Lc 15:29). Pablo exhorta a los creyentes a servir al Señor con fervor (Ro 12:11) y celebra la conversión de los tesalonicenses que se volvieron de los ídolos ''para servir al Dios vivo'' (1 Ts 1:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65865, 'spa', 'Servir en el sentido específico de estar esclavizado, vivir en servidumbre o est', 'Servir en el sentido específico de estar esclavizado, vivir en servidumbre o estar subyugado, ya sea literal o metafóricamente. En Juan 8:33, los judíos protestan que nunca ''han sido esclavos'' de nadie. Dios le dice a Abraham que sus descendientes ''servirán'' a una nación extranjera (Hch 7:7). Pablo emplea este sentido para la esclavitud al pecado (Ro 6:6), a los elementos débiles y pobres (Gá 4:8-9) y a la ley (Gá 4:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65877, 'spa', 'Sierva del Señor', 'Las tres apariciones se centran en mujeres que sirven al Señor. En Lucas 1:38, María responde al ángel: ''He aquí la sierva del Señor'', y en 1:48 profetiza que todas las generaciones la llamarán bienaventurada porque Dios ''miró la humilde condición de su sierva.'' Hechos 2:18 cita a Joel 2:29, prometiendo que en los últimos días Dios derramará su Espíritu también sobre siervos y siervas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65878, 'spa', 'esclavo, siervo', 'Persona sometida a un amo, desde esclavos literales en contextos domésticos y económicos (Mt 18:26-27; Mt 24:45-46) hasta la autodesignación de apóstoles y creyentes como siervos de Cristo (Ro 1:1; Gá 1:10; Fil 1:1). El término conlleva todo el peso del estatus esclavista grecorromano: ausencia de autodeterminación y disponibilidad total ante la voluntad del señor. El español distingue «esclavo» (literal) y «siervo» (dignificado).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65891, 'spa', 'Ser esclavizado', 'Ser esclavizado, hallarse en estado de servidumbre — formas pasivas y estativas que indican sujeción. En Romanos 6:18 y 6:22 los creyentes son descritos como liberados de la esclavitud del pecado y hechos siervos de la justicia. Gálatas 4:3 recuerda el tiempo en que estábamos esclavizados bajo los principios elementales, y Tito 2:3 advierte contra ser esclavas del exceso de vino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65893, 'spa', 'Esclavizar activamente', 'Esclavizar de forma activa, someter a alguien a servidumbre o hacerse esclavo voluntariamente de otros. En Hechos 7:6 Dios anuncia que una nación extranjera esclavizará a Israel durante cuatrocientos años. Pablo declara audazmente en 1 Corintios 9:19 que se hizo esclavo de todos para ganar al mayor número posible, una autosujeción voluntaria y paradójica. En 2 Pedro 2:19 los falsos maestros prometen libertad mientras ellos mismos son esclavos de la corrupción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65899, 'spa', 'Banquete festivo', 'Ambas apariciones en Lucas involucran contextos de banquete: Leví organizando ''un gran banquete'' para Jesús con publicanos y pecadores (Lucas 5:29), y Jesús enseñando sobre invitar a los pobres cuando se dé ''un banquete'' (Lucas 14:13). El término designa una reunión de comida festiva donde los invitados son recibidos y honrados, sirviendo en Lucas como escenario para el compañerismo radical de mesa de Jesús y su enseñanza sobre la hospitalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65900, 'spa', 'Dragón, monstruo serpentino — un gran monstruo serpentino o reptiliano, usado ex', 'Dragón, monstruo serpentino — un gran monstruo serpentino o reptiliano, usado exclusivamente en Apocalipsis como símbolo de Satanás. El dragón es presentado como una criatura rojo fuego con siete cabezas y diez cuernos (Ap 12:3), libra guerra en el cielo contra Miguel (Ap 12:7), es identificado como la serpiente antigua y el Diablo (Ap 12:9, 20:2), otorga poder a la bestia del mar (Ap 13:2-4), y finalmente es atado y arrojado al abismo (Ap 20:1-3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65901, 'spa', 'Agarrar, atrapar', 'En 1 Corintios 3:19, se cita la declaracion de Job de que Dios ''atrapa a los sabios en su propia astucia'', asiendolos en las mismas tramas que urden. El verbo describe la accion de agarrar firmemente con la mano, como quien captura una presa. Dios vuelve la astucia humana en contra de si misma, atrapando a los intrigantes en sus propias maquinaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65902, 'spa', 'Moneda de plata', 'Las tres apariciones neotestamentarias se concentran en Lucas 15:8-9. La mujer posee diez dracmas y pierde una; entonces enciende una lámpara, barre la casa y busca con diligencia hasta encontrarla. Al recuperarla, convoca a amigas y vecinas para que se regocijen con ella. La moneda representa tanto valor económico, quizá el jornal de un día, como un tesoro personal, posiblemente parte de una dote nupcial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65903, 'spa', 'Hoz', 'Hoja curva o instrumento de siega utilizado para cosechar grano, empleado tanto en imágenes agrícolas literales (Marcos 4:29, donde el labrador mete la hoz al llegar la cosecha) como en poderoso símbolo de juicio escatológico (Apocalipsis 14:14-19, donde el Hijo del Hombre y los ángeles siegan la tierra con hoces afiladas). Pese al cambio de parábola pastoral a visión apocalíptica, el referente concreto permanece idéntico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65905, 'spa', 'Carrera de la fe', 'En Hechos 13:25, Juan el Bautista habla de completar su carrera. Hechos 20:24 recoge la célebre declaración de Pablo de que su vida nada vale con tal de acabar su carrera y el ministerio recibido del Señor Jesús. En 2 Timoteo 4:7, Pablo escribe desde la prisión: ''He peleado la buena batalla, he acabado la carrera, he guardado la fe.'' El término vincula esfuerzo atlético con fidelidad ministerial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65906, 'spa', 'Nombre propio, Drusila', 'Hechos 24:24 identifica a Drusila como la esposa de Felix (ella misma judia, hija de Herodes Agripa I), presente durante el testimonio de Pablo. Su nombre latino refleja el dominio cultural romano. Su presencia durante la exposicion de Pablo sobre ''la justicia, el dominio propio y el juicio venidero'' pudo haber resultado particularmente incomoda dadas las circunstancias de su matrimonio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65907, 'spa', 'poder, ser capaz', 'Sentido verbal nuclear de poseer capacidad o poder para hacer algo: «poder», «ser capaz». Se emplea en todas las personas, tiempos y modos para expresar capacidad práctica, moral o divina. «Dios puede de estas piedras levantar hijos a Abraham» (Mt 3:9); «nadie puede servir a dos señores» (Mt 6:24); «si puedes hacer algo, ten compasión» (Mr 9:22). El español «puede» traduce directamente esta función modal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65916, 'spa', 'el poderoso, el que puede', 'Uso sustantivado o participial atributivo donde δυνάμενος funciona como sustantivo o adjetivo: «el poderoso», «el que puede». Dios es descrito como «el que puede destruir alma y cuerpo en el Gehena» (Mt 10:28), y Pablo confía en «aquel que es poderoso para guardar lo que le he encomendado» (2 Ti 1:12). El español «es poderoso» desplaza el verbo modal hacia la categoría de atributo o título divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65953, 'spa', 'poder, fuerza', 'Poder inherente, fuerza o potencia (90x): la capacidad o energía abstracta, sea divina, espiritual o humana. Abarca el poder de Dios (Mt 22:29 «no conocéis el poder de Dios»), el poder del Espíritu (Lc 1:35; 4:14; Hch 1:8), el poder escatológico (Mt 24:30 «viniendo con poder y gran gloria») y el poder conferido a los creyentes. El español «poder» traduce con precisión este núcleo semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65954, 'spa', 'milagros, obras poderosas', 'Obras milagrosas, prodigios (plural, 16x): actos concretos de poder sobrenatural realizados por Dios o sus agentes. Jesús reprocha a las ciudades donde «se habían hecho la mayoría de sus milagros» (Mt 11:20-23), los nazarenos preguntan «¿qué obras poderosas hace?» (Mt 13:54; Mr 6:2), y Pablo enumera «milagros» entre los dones del Espíritu (1 Co 12:10, 28-29). El plural marca actos discretos y observables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65956, 'spa', 'potencias, fuerzas cósmicas', 'Poderes sobrenaturales, fuerzas cósmicas (plural, 10x): seres espirituales o angélicos entendidos como potencias personificadas que operan en los cielos. Las «potencias de los cielos» serán conmovidas en el ésjaton (Mt 24:29; Mr 13:25; Lc 21:26), y Pablo declara que ni «potencias» ni ninguna otra fuerza cósmica podrán separarnos del amor de Dios (Ro 8:38). Aquí δύναμις designa entidades, no atributos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65960, 'spa', 'milagro, obra poderosa', 'Un acto milagroso individual, una obra de poder singular (2x): un evento sobrenatural visto como hecho puntual y no como categoría. En Mr 6:5 Jesús «no pudo hacer allí ningún milagro», y en Mr 9:39 dice «nadie que haga un milagro en mi nombre podrá luego hablar mal de mí». El singular destaca la unicidad del acto frente al plural que designa la categoría general de prodigios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65967, 'spa', 'significado, sentido', 'Significado, fuerza de una expresión verbal (1x): lo que un sonido hablado comunica. En 1 Co 14:11 Pablo escribe «si yo no sé el significado (δύναμιν) de la lengua, seré extranjero para el que habla». Esta extensión singular trata a δύναμις como el «poder» semántico que porta una palabra: su capacidad de transmitir sentido. El español «significado» confirma el desplazamiento de la fuerza física a la comunicativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65971, 'spa', 'capacidad, aptitud', 'Capacidad práctica, aptitud personal (1x): habilidad para realizar algo, con énfasis en el talento individual más que en la fuerza bruta. En la parábola de los talentos (Mt 25:15), el señor distribuye recursos «a cada uno conforme a su capacidad (δύναμιν)». Aquí δύναμις no es poder divino ni milagro, sino competencia medida y proporcional. El español «capacidad» capta con exactitud esta dimensión pragmática e individualizada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65974, 'spa', 'Empoderamiento divino', 'Ambos usos involucran empoderamiento divino: creyentes ''siendo fortalecidos'' con el glorioso poder de Dios para la perseverancia paciente (Colosenses 1:11: español ''siendo fortalecidos''), y fieles que ''fueron fortalecidos'' de la debilidad por la fe (Hebreos 11:34: español ''fueron fortalecidos''). La voz pasiva enfatiza que el poder viene de fuera—Dios fortaleciendo a aquellos que de otra manera serían débiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65975, 'spa', 'Gobernante poderoso', 'Las tres apariciones en el NT abarcan todo el espectro del poder. En Lucas 1:52 el Magnificat proclama que Dios ''derribó de sus tronos a los poderosos'', dinastas terrenales desplazados por la inversión divina. Hechos 8:27 lo aplica al eunuco etíope, alto ministro de la reina Candace encargado de todo su tesoro. Primera Timoteo 6:15 lo atribuye a Dios como ''el bienaventurado y único Soberano''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65976, 'spa', 'Capacidad divina', 'En Romanos 14:4 Pablo defiende al creyente que come: ''el Señor es poderoso para hacerle estar firme'', afirmando el poder de Dios para sostener al fiel. Segunda Corintios 9:8 promete provisión abundante: ''Dios es poderoso para hacer que toda gracia abunde en vosotros.'' En 2 Corintios 13:3 Pablo desafía a quienes buscan prueba de que Cristo habla en él, quien ''no es débil para con vosotros, sino poderoso entre vosotros''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65977, 'spa', 'posible', 'posible');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65978, 'spa', 'poderoso, fuerte', 'poderoso, fuerte');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65979, 'spa', 'capaz, competente', 'capaz, competente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65985, 'spa', 'Puesta del sol', 'Ambas apariciones marcan el fin del sábado cuando las multitudes podían traer a los enfermos a Jesús: ''cuando el sol se puso'' en Capernaúm (Marcos 1:32: español ''se puso''), y ''mientras el sol se ponía'' (Lucas 4:40). El fenómeno natural del atardecer funciona como el marcador temporal que libera a las personas de las restricciones de viaje del sábado, explicando el momento en que las multitudes traen a los enfermos para sanación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65986, 'spa', 'dos (numeral cardinal)', 'El número cardinal dos, que designa un par o la cantidad de dos personas o cosas. Se usa atributivamente con sustantivos («dos discípulos», Mt 11:2; «dos peces», Mt 14:17) y sustantivamente («los envió de dos en dos», Mr 6:7). Más allá de la mera enumeración, porta peso legal y teológico: el requisito mosaico de dos testigos (Dt 19:15, ecoado en Mt 18:16; 2 Co 13:1), la imposibilidad de servir a dos amos (Mt 6:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65988, 'spa', 'Cargas del legalismo', 'Aplicado a las cargas pesadas del legalismo religioso, este sentido captura la naturaleza opresiva de las cargas impuestas sobre otros sin ayuda. El patrón de traducción consistente entre idiomas (español ''difíciles de llevar'', francés ''difficile à porter'') destaca el matiz de ''difícil de llevar'' más que la mera pesadez. Ambas ocurrencias aparecen en la denuncia de Jesús contra los escribas y fariseos, enfatizando la hipocresía de exigir lo que uno mismo no está dispuesto a ayudar a llevar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65989, 'spa', 'Disentería', 'Hechos 28:8 registra que el padre de Publio yacía enfermo con fiebre y disentería, una grave enfermedad intestinal que causa diarrea severa y deshidratación. Lucas emplea el término médico técnico conocido en los escritos hipocráticos. La sanidad de Pablo mediante la oración demuestra el poder divino sobre esta peligrosa condición, abriendo puertas para el ministerio en Malta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65990, 'spa', 'Difícil de explicar', 'Hebreos 5:11 reconoce que la enseñanza sobre el sacerdocio de Melquisedec es «difícil de explicar», no por ser imposiblemente compleja, sino porque la audiencia se había vuelto «tarda para oír». El adjetivo describe algo arduo de interpretar o expresar con claridad. El autor señala la inmadurez espiritual de sus destinatarios, no la oscuridad de la doctrina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65991, 'spa', 'Difícil o arduo', 'Marcos 10:24 recoge la observación de Jesús acerca de lo «difícil» que resulta para los ricos entrar en el reino de Dios. El adjetivo describe algo genuinamente arduo o trabajoso, aunque no imposible. El asombro de los discípulos revela que asumían que la riqueza era señal de bendición divina; Jesús corrige esa idea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65992, 'spa', 'Dificultad extrema', 'Las tres apariciones se encuentran en los relatos sinópticos paralelos de la enseñanza de Jesús tras la partida del joven rico. Mateo 19:23, Marcos 10:23 y Lucas 18:24 registran declaraciones casi idénticas: ''¡Cuán difícilmente entrarán en el reino de Dios los que tienen riquezas!'' El contexto —el asombro de los discípulos y la metáfora del camello por el ojo de una aguja— subraya que esta dificultad roza la imposibilidad humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65993, 'spa', 'Occidente, poniente', 'El occidente, la direccion de la puesta del sol, usado tipicamente en plural y emparejado con ''oriente'' (anatolai) para expresar totalidad geografica. Jesus emplea el merismo oriente-occidente para declarar que personas de toda procedencia entraran en el reino (Mat 8:11; Luc 13:29). La venida del Hijo del Hombre se compara con un relampago que cruza de oriente a occidente (Mat 24:27). En sentido practico, una nube que sube del occidente anuncia lluvia (Luc 12:54).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65994, 'spa', 'Difícil de entender', '2 Pedro 3:16 admite que algunos escritos de Pablo contienen cosas «difíciles de entender», las cuales personas inestables distorsionan. El adjetivo enfatiza la dificultad intelectual para captar el significado. Pedro no excusa la confusión, sino que advierte que la dificultad convierte las Escrituras en vulnerables a la tergiversación por parte de quienes carecen de fundamento doctrinal sólido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65995, 'spa', 'Difamación ministerial', 'La experiencia pasiva de calumnia y mala fama aparece en los catálogos paulinos del sufrimiento apostólico. La evidencia multilingüe muestra tanto el estado activo (''siendo difamados'' en español) como el resultado (''mala fama'' - reputación dañada). Ambos pasajes corintios presentan esto como una realidad esperada del ministerio del evangelio, posicionada junto a otras formas de oposición y dificultad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65996, 'spa', 'doce', 'El numero cardinal doce, empleado en el conteo ordinario (Mt 9:20, doce anos; Mt 14:20, doce canastas) y como designacion teologicamente cargada para los doce apostoles (Mt 10:1-2; 1 Co 15:5), evocando deliberadamente las doce tribus de Israel. Todas las lenguas de destino lo traducen con su numeral estandar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66001, 'spa', 'Duodécimo', 'Apocalipsis 21:20 identifica la duodécima piedra de fundamento de la Nueva Jerusalén como amatista. Se trata de una simple numeración ordinal: la última en la secuencia de doce fundamentos que representan a los doce apóstoles. El número doce en Apocalipsis simboliza plenitud y la totalidad del pueblo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66002, 'spa', 'Las doce tribus', 'En Hechos 26:7, Pablo se refiere a ''nuestras doce tribus'' que sirven a Dios con la esperanza de la promesa de la resurrección. El término designa colectivamente a Israel como la nación completa de doce tribus, a pesar de la dispersión histórica. Pablo afirma así la continuidad entre la antigua esperanza de Israel y la fe en la resurrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66003, 'spa', 'Azotea, techo plano', 'El techo plano o azotea de un edificio, rasgo distintivo de la arquitectura del Cercano Oriente antiguo que funcionaba como espacio habitable al aire libre. Usado para la proclamacion publica (Mat 10:27; Luc 12:3, ''lo que habeis oido al oido, proclamadlo desde las azoteas''), como escenario de acciones dramaticas (Luc 5:19, descenso del paralitico por el techo; Hch 10:9, Pedro orando en la azotea), y en advertencias escatologicas sobre la urgencia de huir sin detenerse (Mat 24:17; Mc 13:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66007, 'spa', 'Don, regalo gratuito — un don gratuito e inmerecido, usado casi exclusivamente p', 'Don, regalo gratuito — un don gratuito e inmerecido, usado casi exclusivamente para referirse a la generosa dádiva de Dios. El don del Espíritu Santo en Pentecostés (Hechos 2:38) y a los gentiles (Hechos 10:45; 11:17), que no puede comprarse con dinero (Hechos 8:20). El don de Dios revelado a la mujer samaritana (Juan 4:10). El ''don gratuito'' de la gracia que supera la transgresión de Adán (Romanos 5:15, 17), la gracia dada para el ministerio (Efesios 3:7; 4:7) y el ''don celestial'' gustado por los creyentes (Hebreos 6:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66009, 'spa', 'Gratuitamente', 'Gratuitamente, sin pago ni costo — el sentido predominante en el Nuevo Testamento. Jesús ordena ''de gratis recibisteis, dad de gratis'' (Mt 10:8); Pablo trabaja ''sin cobrar nada'' (2 Ts 3:8) y proclama la justificación ''como don gratuito'' (Ro 3:24). Las siete apariciones con este sentido subrayan la gratuidad del favor divino y la generosidad que debe caracterizar a los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66010, 'spa', 'Sin causa', 'Sin causa ni motivo — un giro desde ''sin costo'' hacia ''sin fundamento''. En Juan 15:25, Jesús cita el Salmo 35:19: ''me aborrecieron sin causa''. El español ''sin causa'' capta con precisión ese vacío causal, señalando un odio injustificado e irracional dirigido contra Cristo, cumpliendo así la profecía de los salmos sobre el sufrimiento del justo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66011, 'spa', 'En vano', 'Sin propósito, en vano — el sentido de futilidad o inutilidad. En Gálatas 2:21, Pablo argumenta que si la justicia se obtuviera por la ley, entonces Cristo habría muerto ''en vano''. La expresión española ''en vano'' distingue este sentido con nitidez de los de ''gratuitamente'' y ''sin causa'', resaltando la fuerza retórica paulina: la gracia convertida en algo sin propósito sería el desperdicio supremo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66012, 'spa', 'Don gratuito', 'Marcos 15:45 relata que Pilato, al confirmar la muerte de Jesús por medio del centurión, ''concedió el cuerpo a José'', un favor otorgado al discípulo que lo solicitó. Segunda Pedro 1:3 celebra que el poder divino ''nos ha concedido todo lo que pertenece a la vida y a la piedad'', mientras que 1:4 continúa: ''nos ha dado sus preciosas y grandísimas promesas''. El verbo destaca la generosidad libre y sin condiciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66013, 'spa', 'Dones divinos', 'Refiriéndose a dones divinos, este sentido enfatiza el carácter libre y gracioso del dar de Dios. Romanos 5:16 contrasta el don con la condenación, destacando su carácter inmerecido, mientras que Santiago 1:17 ubica todos los buenos dones en la naturaleza generosa de Dios. La traducción consistente como ''don'' o ''regalo'' entre idiomas refleja su significado directo como algo otorgado libremente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66015, 'spa', 'Don, ofrenda', 'Don, ofrenda: regalo u ofrenda llevado ante Dios o presentado en honor. Cubre los regalos de tributo de los Magos (Mt 2:11), las ofrendas del altar que deben esperar la reconciliacion (Mt 5:23-24), las declaraciones de Corban que dedican propiedades al templo (Mr 7:11), y la formula emparejada de dones-y-sacrificios sacerdotales en Hebreos (5:1; 8:3-4; 9:9). El espanol distingue entre ''ofrenda'' (ofrenda ritual) y ''don'' (regalo/dadiva), revelando el doble registro de la palabra entre la entrega sagrada y la general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66019, 'spa', 'Exclamación de alarma', 'En Lucas 4:34 se registra el grito del endemoniado: ''¡Ah! ¿Qué tenemos que ver contigo, Jesús?'', donde el demonio reconoce a Jesús y protesta contra su intervención. La interjección expresa alarma, sorpresa o reconocimiento. El grito involuntario del demonio revela tanto un conocimiento sobrenatural de la identidad de Jesús como temor ante su autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66020, 'spa', 'si, en caso de que', 'Conjunción condicional que introduce una prótasis cuyo cumplimiento se presenta como posible pero incierto, regularmente seguida de subjuntivo. Enmarca la cláusula ''si'' de las condiciones de tercer tipo, donde el hablante ni afirma ni niega el resultado. Pasajes clave incluyen Mt 5:13 (''si la sal pierde su sabor'') y 1 Jn 1:9 (''si confesamos nuestros pecados''), donde la contingencia abierta es teológicamente decisiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66025, 'spa', 'reflexivo directo/indirecto', 'Uso reflexivo nuclear donde el sujeto actúa sobre sí mismo como objeto directo o indirecto: ''niéguese a sí mismo'' (Mt 16:24), ''el que se humilla'' (Mt 23:12). Abarca todas las personas — a sí mismo, a sí misma, a sí mismos — unificadas por la función gramatical de correferencia con el sujeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66028, 'spa', 'reflexivo posesivo', 'Genitivo o posesivo reflexivo que indica pertenencia relativa al sujeto: ''sus propios muertos'' (Mt 8:22), ''sus propios mantos'' (Mt 21:8), ''sus propias lámparas'' (Mt 25:1). El énfasis recae en la identidad del poseedor con el sujeto, expresado en español mediante ''su propio'' o ''de sí mismo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66041, 'spa', 'recíproco (unos a otros)', 'Uso recíproco donde el pronombre reflexivo funciona como equivalente de ἀλλήλων (''unos a otros''), indicando acción mutua entre miembros de un grupo. En Lc 22:17 Jesús dice ''repartidlo entre vosotros'', y en Mt 27:35 los soldados echan suertes ''entre sí''. El contexto — siempre sujetos plurales que actúan mutuamente — señala el desplazamiento hacia el sentido recíproco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66052, 'spa', 'intensivo o comparativo', 'Uso reflexivo intensivo o comparativo en contextos donde el pronombre enfatiza grado o comparación: ''peor que él mismo'' (Mt 12:45, Lc 11:26). Ambas apariciones describen un espíritu inmundo que regresa con otros siete más malvados ''que él mismo'', empleando el genitivo reflexivo en construcción comparativa. El español ''que sí mismo'' capta este matiz enfático.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66077, 'spa', 'Permitir, dejar, consentir — permitir o dejar que algo ocurra, con un matiz de d', 'Permitir, dejar, consentir — permitir o dejar que algo ocurra, con un matiz de dejar en paz. Jesús prohíbe a los demonios hablar (Lucas 4:41), consiente su propio arresto (Lucas 22:51). El Espíritu impide la entrada a Bitinia (Hechos 16:7), Dios permitió a las naciones seguir sus propios caminos (Hechos 14:16), el dueño de casa no habría permitido el robo (Mateo 24:43). En sentido extendido: marineros dejando las anclas en el mar (Hechos 27:40).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66086, 'spa', 'Número cardinal setenta', 'El número cardinal setenta, usado para contar personas específicas o como parte de cifras mayores. Porta resonancia simbólica desde los setenta ancianos de Israel (Números 11:16), eco que resuena cuando Jesús envía a los Setenta (Lucas 10:1, 17). Esteban cita setenta y cinco familiares que entraron en Egipto (Hechos 7:14), mientras que Hechos 23:23 registra setenta jinetes en una escolta militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66087, 'spa', 'Setenta veces', 'En Mateo 18:22, Jesús le dice a Pedro que perdone ''setenta veces siete'', un número tan grande que equivale a un perdón ilimitado, no a un conteo literal. El adverbio enfatiza la acción repetida. Jesús invierte deliberadamente la jactancia de Lamec sobre la venganza multiplicada (Gn 4:24), transformando el principio de la represalia en el principio del perdón sin fin.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66088, 'spa', 'Séptimo', 'El número ordinal ''séptimo'', que marca la séptima posición en una secuencia contada. En el Nuevo Testamento aparece en contextos donde lo séptimo lleva una significación temática especial: la hora séptima de un milagro de sanidad (Jn 4:52), el séptimo día del reposo divino de la creación (He 4:4), la posición genealógica de Enoc como séptimo desde Adán (Judas 1:14), y el séptimo sello y el séptimo ángel en la secuencia apocalíptica de Apocalipsis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66091, 'spa', 'Patriarca Éber', 'En Lucas 3:35, Éber aparece en la genealogía de Jesús, vinculando a Cristo con los patriarcas hebreos descendientes de Sem. Su nombre puede estar etimológicamente conectado con ''hebreo'' como designación étnica. La precisión genealógica de Lucas demuestra la inserción auténtica de Jesús en el linaje histórico de Israel, trazando su descendencia humana hasta los orígenes de la humanidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66092, 'spa', 'Lengua hebrea', 'En Lucas 23:38 (en ciertos manuscritos) se señala que la inscripción de la cruz estaba escrita en hebreo, griego y latín. El adjetivo designa la lengua y la escritura del pueblo judío. La proclamación trilingüe aseguraba la máxima difusión del mensaje: peregrinos judíos, gentiles de habla griega y funcionarios romanos podían leer la acusación sobre Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66093, 'spa', 'Israelita hebraizante', 'Persona de identidad hebrea, particularmente quien conserva la lengua semítica ancestral y las tradiciones, a diferencia de los judíos helenizados. En Hechos 6:1 los Ἑβραῖοι se contrastan con los Ἑλληνισταί en la distribución diaria, mientras que en 2 Corintios 11:22 y Filipenses 3:5 Pablo invoca este título para afirmar su impecable linaje judío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66094, 'spa', 'Lengua hebrea/aramea', 'Las tres apariciones describen a Pablo dirigiéndose a audiencias judías en su lengua materna. En Hechos 21:40 Pablo pide permiso para hablar y, ''de pie en las gradas, hizo señas al pueblo y, hecho un gran silencio, les habló en lengua hebrea''. Hechos 22:2 registra la reacción de la multitud: al oír que les hablaba en hebreo, guardaron aún más silencio. Esta elección deliberada generaba confianza e identidad compartida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66095, 'spa', 'En hebreo/arameo', 'En la lengua hebrea (o aramea), adverbio usado para identificar el idioma semitico en que se expresa un nombre o frase. Aparece exclusivamente en el Evangelio de Juan, donde el evangelista introduce terminos semiticos a un publico lector de griego y ofrece su traduccion: ''que en hebreo se llama Betesda'' (Jn 5:2), ''Gabata'' (19:13), ''Golgota'' (19:17), ''Raboni'' (20:16). En Juan 19:20 distingue el hebreo del latin y el griego en la inscripcion trilingue de la cruz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66096, 'spa', 'acercarse temporalmente', 'acercarse temporalmente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66097, 'spa', 'aproximarse espacialmente', 'aproximarse espacialmente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66108, 'spa', 'acercarse a Dios', 'acercarse a Dios');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66116, 'spa', 'Inscribir permanentemente', 'En Lucas 10:20 Jesús dice a los setenta y dos que se alegren porque sus nombres están inscritos en el cielo, registrados en el libro permanente de Dios. En 2 Corintios 3:2-3 Pablo emplea la metáfora de la carta viva: los creyentes son una carta escrita en los corazones, no con tinta sino por el Espíritu del Dios viviente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66117, 'spa', 'Garante del pacto', 'Hebreos 7:22 llama a Jesús el «garante» de un pacto superior: Él mismo asegura todas sus promesas mediante su obra sacerdotal. El sustantivo describe a un fiador o avalista que se compromete a garantizar el cumplimiento de obligaciones. A diferencia de los sacerdotes levíticos que morían y fallaban, Jesús vive para siempre y garantiza perfectamente lo que promete.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66118, 'spa', 'cerca, próximo (proximidad espacial o temporal)', 'cerca, próximo (proximidad espacial o temporal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66122, 'spa', 'Proximidad progresiva', 'Romanos 13:11 declara que la salvación está «más cerca» ahora que cuando los creyentes depositaron su fe en Cristo: el retorno del Señor se acerca progresivamente. El adverbio comparativo indica distancia o tiempo reducido. Pablo motiva así a una santidad urgente, pues el reloj escatológico avanza sin pausa y cada momento acerca más la consumación prometida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66123, 'spa', 'resucitar (activo transitivo)', 'Resurrección activa transitiva: un agente divino resucita a alguien de entre los muertos. El sujeto es típicamente Dios (Hch 2:24, ''Dios lo resucitó'') o Jesús comisionando a los discípulos (Mt 10:8, ''resucitad muertos''). Se distingue del sentido 1 por tener un agente explícito que realiza la resurrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66124, 'spa', 'ser resucitado / resucitar', 'Pasiva o intransitiva media de resurrección: el sujeto es resucitado de entre los muertos o vuelve a la vida. Es el sentido teológicamente dominante del NT, presente en fórmulas credales (1 Co 15:4 ἐγήγερται, ''ha resucitado'') y a lo largo de los relatos evangélicos. La pasiva divina es fundamental: ''ha resucitado'' preserva la implicación de que Dios es el agente tácito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66125, 'spa', 'levantarse físicamente', 'Uso intransitivo o medio que significa levantarse físicamente, ponerse de pie o alzarse para actuar. Aparece frecuentemente como imperativo — Ἔγειρε, ''¡Levántate!'' (Mt 9:5 al paralítico) — o en transiciones narrativas donde alguien se levanta para obrar (Mt 1:24, José se levantó; Mt 2:13-14, levantándose para huir a Egipto).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66129, 'spa', 'levantar físicamente', 'Acción transitiva de levantar físicamente: alzar a alguien, ayudarle a ponerse de pie, sin referencia a la resurrección. Jesús toma al muchacho enfermo de la mano y ''lo levantó'' (Mr 9:27), Pedro ''levantó'' al cojo (Hch 3:7), y una oveja es sacada de un hoyo (Mt 12:11). Lc 1:69 extiende esto a Dios ''levantando'' un cuerno de salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66130, 'spa', 'surgir, aparecer (figurado)', 'Uso intransitivo figurado: una persona, profeta o entidad ''surge'' o ''aparece'' en el escenario histórico. Falsos profetas ''se levantarán'' (Mt 24:11, 24), la reina del Sur ''se levantará'' en el juicio (Mt 12:42), y nación ''se levantará contra'' nación (Mt 24:7). Extiende la imagen del levantamiento físico al ámbito del surgimiento histórico y profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66147, 'spa', 'despertar del sueño', 'Despertar o ser despertado del sueño, ya sea transitivamente (despertar a alguien) o intransitivamente (ser despertado). Los discípulos despiertan a Jesús durante la tormenta (Mt 8:25, Mr 4:38), y Pablo exhorta a los efesios: Ἔγειρε ὁ καθεύδων, ''¡Despiértate, tú que duermes!'' (Ef 5:14). Ro 13:11 lo emplea metafóricamente: ''es hora de despertarnos del sueño''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66185, 'spa', 'Resurrección de muertos', 'Mateo 27:53 describe a santos levantándose de sus tumbas «después de la resurrección de Él»: la resurrección de Jesús desencadenó el levantamiento de estos creyentes del Antiguo Testamento. El sustantivo denota el acto de levantar o despertar, especialmente de la muerte. Este acontecimiento misterioso demuestra que la resurrección de Cristo es el fundamento y las primicias de toda resurrección futura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66186, 'spa', 'Espías encubiertos', 'Lucas 20:20 relata cómo los escribas y principales sacerdotes enviaron «espías» disfrazados de personas sinceras para atrapar a Jesús con preguntas políticamente peligrosas sobre los impuestos al César. El término designa agentes secretos que operan de manera encubierta. Su pregunta sobre el tributo fue diseñada como un dilema sin salida, pero Jesús respondió con sabiduría que dejó al descubierto su hipocresía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66187, 'spa', 'Fiesta de la Dedicación', 'Juan 10:22 sitúa a Jesús en Jerusalén durante la Fiesta de la Dedicación (Januká), la festividad invernal que celebra la rededicación del templo en 164 a.C. El término significa «renovación» o «consagración». La presencia de Jesús en esta fiesta que celebraba la restauración del culto en el templo establece el contexto para sus declaraciones sobre ser Él mismo el verdadero templo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66188, 'spa', 'Inauguración de pactos', 'Aplicado a la inauguración de pactos, este sentido enfatiza la consagración requerida para hacer operativo un camino. Hebreos 9:18 se refiere al pacto mosaico no siendo inaugurado sin sangre, mientras que 10:20 habla del camino nuevo y vivo que Cristo inauguró a través del velo. El alemán ''einweihen'' (dedicar/consagrar) captura particularmente la dimensión ceremonial de hacer algo sagrado y accesible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66189, 'spa', 'Acusar, presentar cargos', 'Presentar una acusación legal formal contra alguien en un contexto judicial. Cada aparición en el NT se sitúa en un tribunal o asamblea legal: el secretario de Éfeso advierte que las quejas deben resolverse en asamblea legítima (Hch 19:38–40), el tribuno busca conocer los cargos contra Pablo (Hch 23:28), y Pablo mismo comparece acusado ante Agripa (Hch 26:2). En Romanos 8:33, Pablo transforma el término en una declaración teológica triunfante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66195, 'spa', 'Abandonar, desamparar — abandonar o desertar a una persona, especialmente en un ', 'Abandonar, desamparar — abandonar o desertar a una persona, especialmente en un momento de necesidad extrema, con profundo peso emocional y teológico. El grito de desolación de Jesús (Mateo 27:46; Marcos 15:34) y la promesa de Dios ''nunca te desampararé'' (Hebreos 13:5) representan los polos opuestos de este sentido. La experiencia personal de Pablo de ser abandonado por Demas y otros (2 Timoteo 4:10, 16) y la profecía del remanente de Isaías aplicada en Romanos ilustran su alcance.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66202, 'spa', 'Abandonar la asamblea — abandonar o descuidar la práctica establecida de congreg', 'Abandonar la asamblea — abandonar o descuidar la práctica establecida de congregarse, una aplicación especializada donde el objeto no es una persona sino una reunión comunitaria. Hebreos 10:25 exhorta a los creyentes a no abandonar ''el congregarnos'', empleando el mismo verbo pero redirigido del abandono interpersonal a la negligencia comunitaria. Esta única ocurrencia se distingue del sentido 1 por su contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66203, 'spa', 'Habitar entre', 'En 2 Pedro 2:8 se describe al justo Lot ''habitando entre'' los sodomitas, cuya conducta inicua atormentaba a diario su alma justa. El participio enfatiza la residencia continua en medio de una comunidad. Pedro emplea a Lot para demostrar que Dios sabe rescatar a los piadosos de las pruebas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66204, 'spa', 'Injertar', 'Injertar una rama en un árbol vivo para que comparta la vitalidad de la raíz. Las seis apariciones en el NT se concentran en Romanos 11:17-24, donde Pablo desarrolla una alegoría extensa del olivo que representa al pueblo del pacto de Dios. Los creyentes gentiles son ramas silvestres injertadas (v. 17), algunas ramas naturales fueron desgajadas (v. 19), y Dios es capaz de volver a injertar las ramas originales (v. 23-24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66208, 'spa', 'Cargos legales formales', 'Refiriéndose a cargos legales formales en un contexto de tribunal romano, este sentido captura acusaciones que requieren investigación judicial. Hechos 23:29 describe el cargo como indigno de muerte, mientras que 25:16 contrasta la justicia romana (escuchar al acusado) con la condena injusta. La evidencia léxica muestra que este es vocabulario técnico legal, usado para denuncias escritas que inician un proceso, haciendo ambos casos claramente forenses.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66209, 'spa', 'Revestirse de', 'En 1 Pedro 5:5 se exhorta a los creyentes a ''revestirse de humildad'' unos para con otros. El verbo en voz media significa ponerse algo como si fuera una prenda. El mandato de Pedro convierte la humildad en una característica visible y constante, la vestidura distintiva de la vida cristiana en comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66210, 'spa', 'Estorbo u obstáculo', 'En 1 Corintios 9:12 Pablo explica su renuncia al sustento económico para no poner ''ningún obstáculo al evangelio de Cristo''. El sustantivo describe un impedimento que bloquea el avance. Pablo anticipa que algunos podrían acusarlo de predicar por dinero, de modo que renuncia a sus derechos legítimos para que nada entorpezca la difusión del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66211, 'spa', 'Estorbar u obstaculizar', 'Impedir, obstruir o estorbar el progreso, interponiéndose en el curso previsto de alguien. La metáfora atlética de Gálatas 5:7 —«¿quién se interpuso en vuestro camino?»— conserva el sentido original de cortar un sendero. Pablo explica sus visitas demoradas como habiendo sido «impedido» por las demandas del ministerio (Romanos 15:22) o por Satanás (1 Tesalonicenses 2:18). En 1 Pedro 3:7, las oraciones mismas pueden ser «estorbadas» por relaciones conyugales quebrantadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66212, 'spa', 'Dominio propio', 'La capacidad de refrenar los propios deseos, apetitos e impulsos mediante disciplina interior. Ya el uso griego clásico (ἐγκράτεια ἡδονῶν καὶ ἐπιθυμιῶν) enmarcaba esto como dominio sobre los placeres y las concupiscencias. En el NT aparece en catálogos éticos (Gá 5:23; 2 P 1:6) y en el incisivo discurso de Pablo ante Félix (Hch 24:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66213, 'spa', 'Autocontrol activo', 'Describiendo la práctica activa del autocontrol, este sentido se aplica tanto a la restricción sexual (1 Cor 7:9) como a la disciplina atlética (9:25). El patrón multilingüe enfatiza la acción reflexiva (''se controla'' en español, ''se maîtriser'' en francés), destacando la agencia personal en dominar los propios deseos. La imagen atlética de Pablo en 9:25 se basa en el riguroso régimen de entrenamiento de los competidores antiguos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66214, 'spa', 'Dominio propio', 'En Tito 1:8 se requiere que los ancianos sean ''dueños de sí mismos'', ejerciendo dominio disciplinado sobre sus deseos e impulsos. El adjetivo describe a quien tiene poder sobre sí mismo y no es esclavo de sus pasiones. Los líderes deben manifestar el fruto del Espíritu en su disciplina personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66215, 'spa', 'Clasificar entre', 'La única ocurrencia en 2 Corintios 10:12 muestra a Pablo criticando a quienes ''se clasifican a sí mismos'' entre los dignos. El español ''incluirnos'' y el francés ''compter parmi'' apuntan a pertenencia contada, mientras que el alemán ''sich vergleichen'' resalta la dimensión evaluativa. El uso clásico confirma el significado de ''incluir entre'' un grupo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66216, 'spa', 'Ocultar dentro', 'El contexto parabolico en Mateo 13:33 describe levadura escondida dentro de harina, donde el verbo enfatiza un ocultamiento intencional con proposito transformador. El espanol ''escondio'' y el frances ''cacher'' traducen directamente ''esconder'', mientras que el uso clasico (''ocultar o esconder en'') confirma la dimension locativa: no solo esconder, sino esconder dentro de algo. La imagen sugiere penetracion y difusion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66217, 'spa', 'Encinta, embarazada', 'Lucas 2:5 describe a Maria como ''estando encinta'' (ἐγκύῳ) durante el viaje del censo. Todos los idiomas emplean sus terminos estandar para el embarazo, demostrando que es un descriptor fisiologico inequivoco. El rango clasico (mujeres, animales, incluso el caballo de Troya ''prenado de silencio'') confirma el significado central de ''contener dentro''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66218, 'spa', 'Ungir, frotar', 'El consejo de Apocalipsis 3:18 de ''ungir tus ojos con colirio'' emplea imagenes medicinales para la sanidad espiritual. Mientras el espanol usa ''ungir'' (connotacion religiosa), el aleman elige ''einreiben'' (frotar), destacando la aplicacion medicinal. El rango clasico abarca tanto la uncion ritual como la friccion farmaceutica, incluyendo el sentido de ''escozor''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66220, 'spa', 'primera persona estándar', 'Uso estándar del pronombre de primera persona singular sin énfasis especial, referencia simple al hablante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66221, 'spa', 'enfático/contrastivo', 'Uso enfático o contrastivo del pronombre, destacando al hablante en oposición o contraste con otros, ''yo mismo'', ''yo (y no otro)''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66248, 'spa', 'Arrasar, derribar', 'Lucas 19:44 contiene la severa profecia de Jesus sobre Jerusalen: los enemigos ''te derribaran por tierra''. El espanol ''derribaran'' y el frances ''raser'' capturan la totalidad de la demolicion. El uso clasico confirma que el verbo significaba ''aplanar como un piso o pavimento'', no un dano parcial sino una nivelacion completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66249, 'spa', 'Suelo, superficie', 'Hechos 22:7 describe a Pablo cayendo ''al suelo'' (εἰς τὸ ἔδαφος) al ser confrontado por el Cristo resucitado. Todos los idiomas emplean su palabra basica para ''suelo/tierra'' (espanol ''suelo'', frances ''sol''). El rango clasico se extendia a cualquier superficie inferior (fondos de barcos, pavimentos, cimientos), pero aqui es la superficie del camino sobre la que Pablo cayo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66250, 'spa', 'Firmeza inquebrantable', 'En 1 Corintios 7:37 se aplica al hombre que «permanece firme en su corazón» respecto a su decisión sobre el matrimonio. La célebre exhortación de 1 Corintios 15:58 concluye el capítulo de la resurrección: «estad firmes e inconmovibles, abundando siempre en la obra del Señor». Colosenses 1:23 condiciona la fe a permanecer «firmes y constantes».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66251, 'spa', 'Fundamento arquitectónico', 'En 1 Timoteo 3:15, este sustantivo poco frecuente describe a la iglesia como «columna y fundamento (ἑδραίωμα) de la verdad». El español ''fundamento'', el inglés ''foundation'' y el alemán ''Grundfeste'' transmiten la idea de soporte y estabilidad arquitectónica. El término no aparece en ningún otro lugar del Nuevo Testamento y es raro en fuentes clásicas, donde significaba ''apoyo'' o ''sostén''. Su emparejamiento con ''columna'' crea un doblete enfático.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66252, 'spa', 'Rey Ezequías', 'Refiriéndose al rey Ezequías en la genealogía de Mateo, este nombre propio aparece dos veces en versículos consecutivos mientras Mateo traza la línea real desde David hasta el exilio. Las transliteraciones en varios idiomas (Hiskia en alemán, Ézéchias en francés) reflejan esfuerzos por reproducir el original hebreo. La inclusión de Ezequías enfatiza la descendencia davídica de Jesús a través de la casa real de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66253, 'spa', 'Culto autoimpuesto', 'El uso único de Colosenses 2:23 critica el «culto voluntario» (ἐθελοθρησκεία), una religión basada en la elección humana y no en el mandato divino. El compuesto combina ''querer/desear'' (ἐθέλω) con ''culto/servicio religioso'' (θρησκεία), creando un término para prácticas que aparentan piedad pero se originan en la voluntad humana. Pablo señala la futilidad de tales prácticas frente a la verdadera vida en Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66254, 'spa', 'Conforme a costumbre', 'En Lucas 2:27, se describe a los padres actuando «conforme a la costumbre (εἰθισμένον) de la Ley» al presentar a Jesús en el templo. El español ''acostumbrado'' y el francés ''habituel'' transmiten la idea de práctica establecida. La forma pasiva perfecta sugiere algo que ha sido convertido en costumbre, algo que se ha vuelto habitual por la repetición, precisamente lo que la ley ritual produce.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66255, 'spa', 'Gobernante provincial', 'En 2 Corintios 11:32 se menciona «al etnarca (ἐθνάρχης) del rey Aretas» que controlaba Damasco. La mayoría de las traducciones transliteran este título político técnico (español ''etnarca'', francés ''ethnarque''), mientras que el alemán usa ''Statthalter'' (gobernador). El uso clásico muestra que los etnarcas gobernaban tribus o naciones, y el título se aplicó a funcionarios judíos en contextos helenísticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66256, 'spa', 'Gentil, pagano', 'Persona de identidad no judía, ajena a la comunidad del pacto de Israel, con connotaciones de desconocimiento de la ley divina o práctica pagana. En Mateo 5:47 y 6:7 Jesús cita la conducta gentil como referente negativo. Mateo 18:17 lo emplea como categoría extrema de exclusión eclesial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66257, 'spa', 'A modo gentil', 'Gálatas 2:14 contiene la reprensión de Pablo a Pedro por su incongruencia: vivir «a la manera gentil» (ἐθνικῶς) mientras obliga a los gentiles a judaizar. El español ''gentílicamente'' y el alemán ''heidnisch'' reflejan la distinción conductual étnica. El adverbio describe prácticas de vida características de los no judíos, particularmente costumbres alimentarias y de mesa compartida. Pablo señala la hipocresía de esta doble vara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66258, 'spa', 'gentiles, naciones no judías', 'Los gentiles — pueblos no judíos colectivamente, a menudo contrastados con Israel y la comunidad del pacto. Este uso cuasi-técnico neotestamentario es el dominante, con 128 apariciones. Ro 1:5 declara el apostolado de Pablo ''entre todas las naciones''; Ro 11:13 lo identifica como ''apóstol de los gentiles''. El contexto teológico distingue este sentido del neutro ''nación''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66260, 'spa', 'nación, pueblo, etnia', 'Una nación, pueblo o grupo étnico como entidad política o cultural, sin el contraste judío-gentil — aplicable a cualquier pueblo, incluido Israel. Mt 24:7 (''se levantará nación contra nación'') lo emplea en sentido geopolítico genérico; Mt 21:43 lo aplica a una futura comunidad del pacto. Este sentido se alinea con el uso singular y político del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66275, 'spa', 'Costumbre, hábito, práctica establecida — una práctica, tradición o modo habitua', 'Costumbre, hábito, práctica establecida — una práctica, tradición o modo habitual de hacer las cosas, particularmente en contextos religiosos o legales. Abarca rituales del templo (Lc 1:9, el sorteo sacerdotal para el incienso), observancia festiva (Lc 2:42, la peregrinación anual de Pascua), costumbres funerarias (Jn 19:40), y tradiciones legales disputadas (Hch 6:14, 15:1, 21:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66277, 'spa', 'Acostumbrar, soler', 'Seguir un patrón establecido de conducta; hacer algo habitualmente o por costumbre. El perfecto εἴωθα funciona como presente denotando hábito arraigado. En Mateo 27:15 describe la costumbre pascual del gobernador; Lucas 4:16 muestra la práctica sabática de Jesús; Hechos 17:2 registra el método misionero habitual de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66278, 'spa', 'si (condicional)', 'Partícula condicional que introduce cláusulas ''si'' en todos los tipos de condiciones: reales (εἰ + indicativo), hipotéticas y preguntas retóricas. Con 442 apariciones es la función dominante, presente en argumentos doctrinales (Ro 8:9, ''si el Espíritu de Dios mora en vosotros''), relatos de tentación (Mt 4:3, ''si eres Hijo de Dios'') e instrucción ética (Mt 5:29-30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66279, 'spa', 'si no, excepto, a menos que', 'La combinación εἰ μή (''si no'') funcionando como marcador exceptivo o restrictivo con el significado de ''excepto, a menos que, solo''. En 65 apariciones niega una generalización precedente e introduce la excepción: ''Nadie conoce al Hijo sino el Padre'' (Mt 11:27), ''la sal que perdió su sabor no sirve para nada sino para ser echada fuera'' (Mt 5:13). El español ''sino'' capta con precisión esta función exceptiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66286, 'spa', 'De otra manera', 'Partícula condicional que significa ''de otra manera'', ''si no'' o ''de lo contrario'', introduciendo la consecuencia que se sigue si una condición expuesta no se cumple. Funciona como pivote lógico en la enseñanza de Jesús — ''de otra manera no tendréis recompensa de vuestro Padre'' (Mt 6:1), ''de lo contrario el vino nuevo reventará los odres'' (Mt 9:17; Lc 5:36-37) — y en la teología paulina — ''de otra manera la gracia ya no es gracia'' (Ro 11:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66288, 'spa', 'Forma o apariencia visible', 'La forma, figura o apariencia visible de algo tal como es percibida por los sentidos; por extensin, una clase o categora. El Espritu aparece en ''forma'' corporal como paloma (Lucas 3:22) y el rostro de Jess cambia de ''apariencia'' en la Transfiguracin (Lucas 9:29). El alemn ''Gestalt'' (figura) capta lo concreto, mientras que ''apariencia'' enfatiza la cualidad percibida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66289, 'spa', 'saber hechos o verdades', 'Poseer conocimiento factual o proposicional — saber que algo es así, comprender una verdad o estar al tanto de una información (285 apariciones). El español ''saber'' corresponde con precisión a este conocimiento cognitivo e intelectual. Prominente en las enseñanzas de Jesús donde apela a lo que los oyentes ya saben (Mt 7:11; 24:42; 25:13) y en argumentos apostólicos construidos sobre conocimiento compartido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66294, 'spa', 'conocer personalmente', 'Conocer a una persona, lugar o cosa mediante encuentro directo o trato personal (36 apariciones). El español lo ilumina con claridad: este sentido se alinea con ''conocer'', que implica familiaridad relacional o experiencial más que conocimiento abstracto. Pilato ''sabía'' (reconocía) que los principales sacerdotes habían entregado a Jesús por envidia (Mt 27:18); los discípulos ''no le conocían'' en sus apariciones posteriores a la resurrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66329, 'spa', 'Templo de ídolos', 'En 1 Corintios 8:10, Pablo confronta la situación polémica de alguien visto «reclinado en un templo de ídolos (εἰδωλείῳ)», participando en banquetes dentro de recintos templarios paganos. Todos los idiomas traducen consistentemente como «templo de ídolos», reconociendo esta designación arquitectónico-religiosa específica. La preocupación de Pablo no es meramente la arquitectura pagana, sino la participación en el culto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66330, 'spa', 'Sacrificado a ídolos, alimento ofrecido a ídolos — alimento, particularmente car', 'Sacrificado a ídolos, alimento ofrecido a ídolos — alimento, particularmente carne, que ha sido ofrecido en sacrificio a una deidad pagana, una cuestión ética apremiante en la iglesia primitiva. El concilio apostólico lo prohíbe (Hechos 15:29; 21:25), Pablo lo aborda extensamente en términos de conciencia y amor hacia los creyentes más débiles (1 Corintios 8:1, 4, 7, 10; 10:19, 28), y el Cristo resucitado condena su tolerancia en las iglesias de Pérgamo y Tiatira (Apocalipsis 2:14, 20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66336, 'spa', 'Idolatría', 'Adoración de ídolos o deidades falsas, abarcando la participación literal en cultos paganos y la elevación metafórica de lo creado a lealtad suprema. Pablo ordena huir de ella en 1 Corintios 10:14 y la extiende a la codicia en Colosenses 3:5. Gálatas 5:20 y 1 Pedro 4:3 la incluyen en catálogos de vicios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66337, 'spa', 'Idólatra, adorador de ídolos', 'Persona que adora ídolos o dioses falsos, literalmente alguien que sirve a imágenes, pero ampliado por Pablo para incluir a todo aquel cuya lealtad más profunda pertenece a algo distinto de Dios. En la correspondencia corintia, los idólatras figuran en catálogos éticos junto a los inmorales sexuales y estafadores (1 Co 5:10–11; 6:9), y 1 Corintios 10:7 recuerda la adoración del becerro de oro de Israel como advertencia. Efesios 5:5 amplía radicalmente el concepto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66340, 'spa', 'Ídolo, imagen de un dios falso — una imagen física o representación de un dios f', 'Ídolo, imagen de un dios falso — una imagen física o representación de un dios falso adorado en la práctica pagana. El becerro de oro en el desierto (Hechos 7:41), contaminaciones que deben evitarse (Hechos 15:20), filosóficamente ''nada'' pero moralmente peligroso (1 Corintios 8:4, 7; 10:19). Pablo confronta a quienes aborrecen los ídolos pero roban templos (Romanos 2:22), los tesalonicenses se convirtieron de los ídolos al Dios vivo (1 Tesalonicenses 1:9), y Apocalipsis lamenta la adoración impenitente de ídolos (Apocalipsis 9:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66345, 'spa', 'En vano, inútilmente', 'Sin resultado, en vano, sin propósito. Se usa adverbialmente para describir acciones o experiencias que no logran producir el resultado previsto. En Ro 13:4 la autoridad gobernante no lleva la espada ''en vano'' (es decir, sin propósito; realmente ejerce justicia). En las epístolas a los gálatas y corintios, Pablo lo emplea como advertencia retórica: el sufrimiento de los gálatas habría sido ''para nada'' si abandonan el evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66346, 'spa', 'El número cardinal veinte, empleado en diversos contextos de conteo y medición', 'El número cardinal veinte, empleado en diversos contextos de conteo y medición. Distancias: veinticinco estadios remados (Jn 6:19), veinte brazas de profundidad (Hch 27:28). Cálculo militar: veinte mil soldados (Lc 14:31). Tamaño de una multitud: ciento veinte en el aposento alto (Hch 1:15). Víctimas: veintitrés mil que cayeron (1 Co 10:8). Consejo celestial: los veinticuatro ancianos alrededor del trono de Dios (Ap 4:4, 10; 5:8; 11:16; 19:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66347, 'spa', 'Ceder o someterse', 'En Gálatas 2:5, Pablo declara firmemente: «no cedimos (εἴξαμεν) en sumisión ni por una hora» ante quienes exigían la circuncisión de los gentiles. El español «cedimos» y el alemán «nachgeben» capturan el sentido de conceder terreno o someterse ante la presión. El aoristo con negación enfática subraya la negativa rotunda de Pablo a comprometer la libertad del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66348, 'spa', 'Introducir comparaciones', 'Introduciendo comparaciones que hacen vívidas las verdades espirituales, este sentido aparece en los símiles memorables de Santiago sobre la fe y el oír. Ambas instancias usan imágenes naturales (olas impulsadas por el viento, el reflejo de un espejo) para iluminar la inestabilidad espiritual y el olvido. El verbo establece la fórmula ''es semejante a'' común en la literatura sapiencial, haciendo tangibles las cualidades abstractas mediante comparación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66349, 'spa', 'Semejanza o representación visible que participa de su original', 'Semejanza o representación visible que participa de su original. Se usa para el retrato del emperador en una moneda (Mt 22:20; Mr 12:16), para los ídolos como representaciones degradadas (Ro 1:23; Ap 13:14-15), para Cristo como imagen del Dios invisible (2 Co 4:4; Col 1:15) y para los creyentes que van siendo transformados a la semejanza de Cristo (Ro 8:29; 2 Co 3:18). El término implica correspondencia real, no mera apariencia. El rango abarca desde retratos numismáticos hasta la gloria cristológica y la idolatría apocalíptica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66352, 'spa', 'Sinceridad transparente', 'En 1 Corintios 5:8 Pablo ordena celebrar la fiesta «con panes sin levadura, de sinceridad y de verdad», aplicando la imagen pascual a la vida cristiana. En 2 Corintios 1:12 defiende su integridad: «nos hemos conducido en el mundo con sencillez y sinceridad de Dios». En 2 Corintios 2:17 contrasta su sinceridad con quienes mercadean la palabra de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66353, 'spa', 'Pureza moral y sinceridad', 'Describiendo pureza moral y espiritual sin mezcla de falsedad, este sentido enfatiza carácter sincero y sin aleación. Filipenses 1:10 lo conecta con discernimiento moral, mientras que 2 Pedro 3:1 lo aplica a mentes libres de error. El significado raíz de ''sin mezcla'' o ''sin aleación'' enriquece la aplicación moral: así como el oro puro no contiene metal base, la fe sincera no contiene hipocresía.');